$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L "var on=\(now-TRG\.t<200\)\?1:0;"
$r1="var on; now=(typeof performance!=='undefined')?performance.now():Date.now(); on=(now-TRG.t<200)?1:0;   // v28.xx (cw-walletonce), HIS NOTE (2026-10-25) on the photo of v34.78: `"Text collisions on the menu thing`". The corner rows are stamped with the real clock, but the loop passed its own frame time: a driven loop (the camera staging, a test) runs ahead of the real clock, the page text came back and printed over the canvas rows. Both sides now read the same clock."
$chk=@'
  {v:'VER',what:'cw-walletonce, his note (text collisions on the menu thing): the page text in the top right corner stays hidden while the canvas rows are drawn, even when the loop is driven with a frame time ahead of the real clock (the camera staging), so the cash figure is named once',
   run:function(){
     if(typeof trHide!=='function'||typeof TRG!=='object') return 'SKIP: no corner hide here';
     var cl=document.body.classList, had=cl.contains('trcol'), h0=TRG.hid, t0=TRG.t, bad=null;
     try{
       cl.remove('trcol'); TRG.hid=0; TRG.t=performance.now();
       trHide(performance.now()+5000);
       if(!cl.contains('trcol')) bad='the page text came back over the canvas rows when the loop ran 5 s ahead of the real clock';
     } finally { TRG.hid=h0; TRG.t=t0; if(had) cl.add('trcol'); else cl.remove('trcol'); }
     return bad; }},
'@.Replace("`r",'')
